 if(!$owner&&in_array($action,['save','upload'],true)&&(int)($_POST['id']??0)>0){$access=db()->prepare('SELECT assigned_employee_id FROM marketing_work_items WHERE id=?');$access->execute([(int)$_POST['id']]);$existing=$access->fetch();if(!$existing||(int)$existing['assigned_employee_id']!==marketing_employee_id())throw new RuntimeException('Work item not found.');}
 if($action==='save'){$id=(int)($_POST['id']??0);$title=trim((string)($_POST['title']??''));if($title==='')throw new RuntimeException('Enter a title.');$type=(string)($_POST['content_type']??'social_post');$assigned=$owner?(int)($_POST['assigned_employee_id']??0):marketing_employee_id();$values=[$title,$type,trim((string)($_POST['platform']??''))?:null,trim((string)($_POST['campaign']??''))?:null,trim((string)($_POST['product_reference']??''))?:null,trim((string)($_POST['brief']??''))?:null,trim((string)($_POST['objective']??''))?:null,trim((string)($_POST['target_audience']??''))?:null,trim((string)($_POST['owner_notes']??''))?:null,trim((string)($_POST['required_dimensions']??''))?:null,$_POST['due_at']?:null,$_POST['publish_at']?:null,(string)($_POST['priority']??'normal'),isset($_POST['approval_required'])?1:0,$assigned?:null,trim((string)($_POST['caption']??''))?:null,trim((string)($_POST['cta']??''))?:null,trim((string)($_POST['hashtags']??''))?:null];if($id){$values[]=$id;db()->prepare('UPDATE marketing_work_items SET title=?,content_type=?,platform=?,campaign=?,product_reference=?,brief=?,objective=?,target_audience=?,owner_notes=?,required_dimensions=?,due_at=?,publish_at=?,priority=?,approval_required=?,assigned_employee_id=?,caption=?,cta=?,hashtags=? WHERE id=?')->execute($values);}else{$values[]=(int)$user['id'];$values[]=(string)$user['name'];db()->prepare('INSERT INTO marketing_work_items(title,content_type,platform,campaign,product_reference,brief,objective,target_audience,owner_notes,required_dimensions,due_at,publish_at,priority,approval_required,assigned_employee_id,caption,cta,hashtags,created_by,created_by_name)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute($values);$id=(int)db()->lastInsertId();db()->prepare("INSERT INTO marketing_item_history(item_id,new_status,note,actor_id,actor_name)VALUES(?,'brief','Work item created',?,?)")->execute([$id,(int)$user['id'],(string)$user['name']]);marketing_notify($id,$assigned,'New marketing brief',$title);}$message='Marketing work saved.';}
 if($action==='status'){$id=(int)$_POST['id'];$status=(string)$_POST['status'];if(!in_array($status,marketing_statuses(),true))throw new RuntimeException('Choose a valid status.');$q=db()->prepare('SELECT * FROM marketing_work_items WHERE id=?');$q->execute([$id]);$item=$q->fetch();if(!$item||(!$owner&&(int)$item['assigned_employee_id']!==marketing_employee_id()))throw new RuntimeException('Work item not found.');if(in_array($status,['approved','cancelled'],true)&&!$owner)throw new RuntimeException('Owner approval is required.');$note=trim((string)($_POST['note']??''));db()->prepare('UPDATE marketing_work_items SET status=?,published_at=IF(?="published",COALESCE(published_at,NOW()),published_at),published_url=COALESCE(NULLIF(?,""),published_url),revision_count=revision_count+IF(?="changes_requested",1,0) WHERE id=?')->execute([$status,$status,(string)($_POST['published_url']??''),$status,$id]);db()->prepare('INSERT INTO marketing_item_history(item_id,old_status,new_status,note,actor_id,actor_name)VALUES(?,?,?,?,?,?)')->execute([$id,$item['status'],$status,$note?:null,(int)$user['id'],(string)$user['name']]);marketing_notify($id,$owner?(int)$item['assigned_employee_id']:(int)$item['created_by'],'Marketing status updated',$item['title'].' is now '.str_replace('_',' ',$status).'.');$message='Status updated.';}
 if($action==='upload'&&!empty($_FILES['asset']['tmp_name'])){$id=(int)$_POST['id'];$file=$_FILES['asset'];if((int)($file['error']??UPLOAD_ERR_OK)!==UPLOAD_ERR_OK)throw new RuntimeException('The file could not be uploaded.');if((int)$file['size']>30*1024*1024)throw new RuntimeException('Files must be 30 MB or smaller.');$dir=BASE_PATH.'/uploads/marketing';if(!is_dir($dir)&&!mkdir($dir,0750,true))throw new RuntimeException('The marketing upload folder is unavailable.');$stored=bin2hex(random_bytes(18)).'-'.preg_replace('/[^A-Za-z0-9._-]/','-',basename((string)$file['name']));if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$stored))throw new RuntimeException('Upload failed.');$count=db()->prepare('SELECT COUNT(*) FROM marketing_item_versions WHERE item_id=?');$count->execute([$id]);$versionNumber=(int)$count->fetchColumn()+1;$label=$versionNumber===1&&$owner?'Original':'Draft '.$versionNumber;db()->prepare('INSERT INTO marketing_item_versions(item_id,version_label,file_name,stored_name,mime_type,file_size,uploaded_by,uploaded_by_name)VALUES(?,?,?,?,?,?,?,?)')->execute([$id,$label,basename((string)$file['name']),$stored,(string)$file['type'],(int)$file['size'],(int)$user['id'],(string)$user['name']]);$message='New file version uploaded.';}
}}
