$params=[];$scope=marketing_scope_sql($params);$view=(string)($_GET['view']??'dashboard');$typeMap=['social'=>['social_post','story','carousel'],'reels'=>['reel'],'whatsapp'=>['whatsapp_post'],'blog'=>['blog'],'newsletter'=>['newsletter'],'website'=>['website_banner','product_image','product_listing','website_update'],'campaigns'=>['campaign_creative','campaign','ad'],'ideas'=>['idea']];$where=$scope;if(isset($typeMap[$view])){$placeholders=implode(',',array_fill(0,count($typeMap[$view]),'?'));$where.=" AND content_type IN ($placeholders)";array_push($params,...$typeMap[$view]);}$q=db()->prepare("SELECT w.*,e.full_name assigned_name,(SELECT COUNT(*) FROM marketing_item_versions v WHERE v.item_id=w.id) version_count FROM marketing_work_items w LEFT JOIN ops_employees e ON e.id=w.assigned_employee_id WHERE $where AND w.cancelled_at IS NULL ORDER BY COALESCE(w.due_at,w.publish_at,'9999-12-31'),w.id DESC LIMIT 250");$q->execute($params);$items=$q->fetchAll();
